document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,t="info"){return`\n      <div class="insight-card ${t}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const t=document.getElementById("store-form"),i=document.getElementById("store-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const a=parseFloat(document.getElementById("website-cost").value),o=parseFloat(document.getElementById("inventory-cost").value),r=parseFloat(document.getElementById("initial-marketing").value),l=parseFloat(document.getElementById("additional-costs").value),d=parseInt(document.getElementById("monthly-traffic").value),c=parseFloat(document.getElementById("conversion-rate").value),p=parseFloat(document.getElementById("average-order").value),v=parseFloat(document.getElementById("gross-margin").value),u=parseFloat(document.getElementById("repeat-rate").value),g=parseFloat(document.getElementById("marketing-cost").value),m=parseFloat(document.getElementById("logistics-cost").value),$=parseFloat(document.getElementById("tech-maintenance").value),b=parseFloat(document.getElementById("staff-costs").value),w=parseFloat(document.getElementById("other-expenses").value);if(d<=0||c<=0||p<=0||v<=0)return i.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const f=a+o+r+l,h=d*(c/100),y=h*p,k=y*(u/100),I=y+k,F=v/100,E=I*F,B=12*I,x=g+m+$+b+w,C=E-x,M=12*C,O=C/I*100,A=f/M,L=M/f*100,R=g/h,P=p*F/(1-u/100),S=P/R,D=E/g*100,T=g/d,V=I/d,U=h/30,q=y*(1-F)/(o/12);let z="info";C<0?z="warning":O>20&&(z="success");let j="info";L<30?j="warning":L>60&&(j="success");let G="info";c<2?G="warning":c>4&&(G="success");let H="info";S<3?H="warning":S>5&&(H="success"),i.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🛒 Online Store Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n(f),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(C),`Margin: ${e(O)}`,z)}\n            ${s("⏱️ Payback Period",`${A.toFixed(1)} years`,`ROI: ${e(L)}`,A<=2?"success":"warning")}\n            ${s("🎯 Conversion Rate",e(c),`${h.toFixed(0)} orders/month`,G)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Website development & design</span>\n                  <span>${n(a)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Initial inventory</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Initial marketing & advertising</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional costs</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(f)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Primary sales (${h.toFixed(0)} orders × $${p})</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Repeat purchases (${e(u)})</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(I)}</strong></span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Gross profit (${e(v)} margin)</span>\n                  <span>${n(E)}</span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Marketing & advertising</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Fulfillment & shipping</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Technology & hosting</span>\n                  <span>${n($)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Staff & personnel</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(x)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${H}">\n              <h6>👥 Customer Metrics</h6>\n              <div class="metric-subtitle">\n                Acquisition cost (CAC): <strong>${n(R)}</strong><br>\n                Lifetime value (LTV): <strong>${n(P)}</strong><br>\n                LTV/CAC ratio: <strong>${S.toFixed(1)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>📊 Marketing Metrics</h6>\n              <div class="metric-subtitle">\n                ROAS: <strong>${e(D)}</strong><br>\n                Cost per visitor: <strong>${n(T)}</strong><br>\n                Revenue per visitor: <strong>${n(V)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${C>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(M)}</strong><br>\n                Weekly profit: <strong>${n(M/52)}</strong><br>\n                Daily profit: <strong>${n(M/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>📦 Operational Metrics</h6>\n              <div class="metric-subtitle">\n                Orders per day: <strong>${U.toFixed(1)}</strong><br>\n                Inventory turnover: <strong>${q.toFixed(1)}x/month</strong><br>\n                Annual revenue: <strong>${n(B)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${O<10?"<li>⚠️ Low profitability. Consider increasing prices or reducing costs.</li>":""}\n              ${c<2?"<li>📍 Low conversion rate. Optimize website UX/UI and product pages.</li>":""}\n              ${S<3?"<li>💰 High acquisition costs. Optimize advertising campaigns and targeting.</li>":""}\n              ${A>2?"<li>⏰ Long payback period. Increase marketing budget or improve conversion.</li>":""}\n              ${c>4?"<li>✅ Excellent conversion rate! Scale up traffic acquisition.</li>":""}\n              ${O>25?"<li>🎉 Outstanding profitability! Consider expanding product lines.</li>":""}\n              <li>🎯 A/B test product pages, checkout process, and pricing strategies.</li>\n              <li>📱 Optimize for mobile - 60%+ of e-commerce traffic is mobile.</li>\n              <li>📧 Implement email marketing campaigns to increase repeat purchases.</li>\n              <li>⭐ Collect and display customer reviews to build trust and credibility.</li>\n              <li>🚚 Improve logistics: fast shipping increases conversion rates.</li>\n              <li>💳 Add multiple payment options for customer convenience.</li>\n              <li>🎁 Create loyalty programs to encourage repeat business.</li>\n              <li>📊 Use Google Analytics and pixels to track ROI accurately.</li>\n              <li>🔍 Invest in SEO to reduce dependence on paid advertising.</li>\n              <li>🤝 Develop affiliate programs and influencer partnerships.</li>\n              <li>💬 Add live chat support to assist customers and reduce cart abandonment.</li>\n              <li>🏆 Implement upselling and cross-selling strategies to increase AOV.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.storeBusinessData={"Monthly Traffic":d,"Conversion Rate (%)":c,"Average Order Value ($)":p,"Total Investment ($)":f,"Monthly Revenue ($)":I,"Gross Profit ($)":E,"Monthly Expenses ($)":x,"Net Profit ($)":C,"Profit Margin (%)":O,"Annual ROI (%)":L,"Payback Period (years)":A,"CAC ($)":R,"LTV ($)":P,"LTV/CAC Ratio":S,"ROAS (%)":D}}),window.downloadCSV=function(){if(!window.storeBusinessData)return;const n=Object.entries(window.storeBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="online-store-business-plan.csv",s.click()}});